/**
 * Helper untuk menyusun definisi langkah SteppedForm berdasarkan kolom aktif dan stepGroups.
 * Menghubungkan setiap step group dengan kolom konkret (termasuk label override & kolom dinamis).
 */
export function getStepGroups(configOrTableName, effectiveColumns = []) {
  const config =
    typeof configOrTableName === 'string'
      ? Object.values(DATA_PAGES).find((p) => p.tableName === configOrTableName) || DATA_PAGES[configOrTableName]
      : configOrTableName;

  if (!config) return [];

  const columns = effectiveColumns.length > 0 ? effectiveColumns : config.columns || [];
  const colMap = new Map(columns.map((c) => [c.key, c]));

  if (!config.stepGroups || config.stepGroups.length === 0) {
    // Fallback: bagi kolom menjadi kelompok berisi maks 8 kolom per langkah
    const chunks = [];
    const size = 8;
    for (let i = 0; i < columns.length; i += size) {
      chunks.push({
        id: `step-${Math.floor(i / size) + 1}`,
        title: `Bagian ${Math.floor(i / size) + 1}`,
        description: `Pengisian data kelompok ${Math.floor(i / size) + 1}`,
        fields: columns.slice(i, i + size),
      });
    }
    return chunks;
  }

  const assignedKeys = new Set();
  const result = config.stepGroups.map((group) => {
    const fields = (group.keys || [])
      .map((k) => {
        assignedKeys.add(k);
        return colMap.get(k);
      })
      .filter(Boolean);

    return {
      id: group.id,
      title: group.title,
      description: group.description,
      fields,
    };
  });

  // Jika ada kolom tambahan/dinamis yang belum masuk ke grup mana pun, masukkan ke grup akhir
  const remainingColumns = columns.filter((c) => !assignedKeys.has(c.key));
  if (remainingColumns.length > 0) {
    result.push({
      id: 'lainnya',
      title: 'Kolom Tambahan',
      description: 'Kolom kustom atau tambahan lainnya',
      fields: remainingColumns,
    });
  }

  return result.filter((g) => g.fields.length > 0);
}

/**
 * Backward-compat alias: caller lama yang masih akses DATA_PAGES.kegiatanWarga.
 * Pointer ke object yang sama dengan rekapDawis. Non-enumerable supaya tidak
 * muncul duplikat di Object.values(DATA_PAGES).
 */
Object.defineProperty(DATA_PAGES, 'kegiatanWarga', {
  value: DATA_PAGES.rekapDawis,
  enumerable: false,
  writable: false,
  configurable: false,
});
